var MIME_TABLE={
  'html':'text/html','htm':'text/html','css':'text/css','js':'application/javascript','mjs':'application/javascript',
  'json':'application/json','jsonld':'application/ld+json','xml':'application/xml','txt':'text/plain','csv':'text/csv','md':'text/markdown','rtf':'application/rtf',
  'yaml':'application/yaml','yml':'application/yaml','toml':'application/toml','ini':'text/plain','env':'text/plain','log':'text/plain','geojson':'application/geo+json',
  'png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','gif':'image/gif','svg':'image/svg+xml','webp':'image/webp','ico':'image/x-icon','bmp':'image/bmp','avif':'image/avif',
  'pdf':'application/pdf','zip':'application/zip','gz':'application/gzip','tgz':'application/gzip','tar':'application/x-tar','7z':'application/x-7z-compressed','rar':'application/vnd.rar',
  'mp3':'audio/mpeg','wav':'audio/wav','ogg':'audio/ogg','flac':'audio/flac','m4a':'audio/mp4','weba':'audio/webm',
  'mp4':'video/mp4','webm':'video/webm','avi':'video/x-msvideo','mov':'video/quicktime','mkv':'video/x-matroska',
  'doc':'application/msword','docx':'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'xls':'application/vnd.ms-excel','xlsx':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'ppt':'application/vnd.ms-powerpoint','pptx':'application/vnd.openxmlformats-officedocument.presentationml.sheet',
  'woff':'font/woff','woff2':'font/woff2','ttf':'font/ttf','otf':'font/otf','eot':'application/vnd.ms-fontobject',
  'wasm':'application/wasm','webmanifest':'application/manifest+json',
  'epub':'application/epub+zip','sqlite':'application/x-sqlite3','bin':'application/octet-stream','exe':'application/octet-stream',
  'gltf':'model/gltf+json','glb':'model/gltf-binary'
};
function normExt(s){ return String(s).toLowerCase().replace(/^\./,'').replace(/\s+/g,''); }
function lookup(ext){ return MIME_TABLE[normExt(ext)] || null; }
function reverse(mime){
  mime=String(mime).toLowerCase().trim();
  var res=[];
  for(var k in MIME_TABLE){ if(MIME_TABLE[k]===mime) res.push(k); }
  return res.length?res:null;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { lookup:lookup, reverse:reverse, normExt:normExt, TABLE:MIME_TABLE };
}
if (typeof window !== 'undefined') {
  window.MimeForgePure = { lookup:lookup, reverse:reverse, normExt:normExt, TABLE:MIME_TABLE };
}
